SELECT  coalesce(json_agg("root" ORDER BY "root.pg.id" ASC NULLS LAST), '[]' ) AS "root" FROM  (SELECT  row_to_json((SELECT  "_e"  FROM  (SELECT  "_root.base"."id" AS "id", "_root.ar.root.articles_aggregate"."articles_aggregate" AS "articles_aggregate", "_root.ar.root.page"."page" AS "page"       ) AS "_e"      ) ) AS "root", "_root.base"."id" AS "root.pg.id" FROM  (SELECT  *  FROM "public"."author"  WHERE ('true')   ORDER BY "id" ASC NULLS LAST  ) AS "_root.base" LEFT OUTER JOIN LATERAL (SELECT  json_build_object('aggregate', json_build_object('count', COUNT(*), 'sum', json_build_object('id', sum("_root.ar.root.articles_aggregate"."root.ar.root.articles_aggregate.pg.id" ) ) ), 'nodes', coalesce(json_agg("root.ar.root.articles_aggregate.f.nodes" ), '[]' ) ) AS "articles_aggregate" FROM  (SELECT  "_root.ar.root.articles_aggregate.base"."id" AS "root.ar.root.articles_aggregate.pg.id", row_to_json((SELECT  "_e"  FROM  (SELECT  "_root.ar.root.articles_aggregate.base"."id" AS "id"       ) AS "_e"      ) ) AS "root.ar.root.articles_aggregate.f.nodes" FROM  (SELECT  *  FROM "public"."article"  WHERE ((("_root.base"."id") = ("author_id")) AND (("public"."article"."author_id") = (('3')::integer)))     ) AS "_root.ar.root.articles_aggregate.base"      ) AS "_root.ar.root.articles_aggregate"      ) AS "_root.ar.root.articles_aggregate" ON ('true') LEFT OUTER JOIN LATERAL (SELECT  json_build_object('aggregate', json_build_object('count', COUNT(*) ), 'nodes', coalesce(json_agg("root.ar.root.page.f.nodes" ORDER BY "root.ar.root.page.pg.id" DESC NULLS FIRST), '[]' ) ) AS "page" FROM  (SELECT  row_to_json((SELECT  "_e"  FROM  (SELECT  "_root.ar.root.page.base"."id" AS "id"       ) AS "_e"      ) ) AS "root.ar.root.page.f.nodes", "_root.ar.root.page.base"."id" AS "root.ar.root.page.pg.id" FROM  (SELECT  *  FROM "public"."article"  WHERE ((("_root.base"."id") = ("author_id")) AND (("public"."article"."author_id") = (('3')::integer)))   ORDER BY "id" DESC NULLS FIRST LIMIT 1 ) AS "_root.ar.root.page.base"    ORDER BY "root.ar.root.page.pg.id" DESC NULLS FIRST  ) AS "_root.ar.root.page"      ) AS "_root.ar.root.page" ON ('true')    ORDER BY "root.pg.id" ASC NULLS LAST  ) AS "_root"
